// WHAT THIS MOUNT HOLDS — the engine version a repo has installed, and the version
// of each pack it has installed, read out of and written back into its settings
// file. One module, because the update flows, the install flow, the vendor writer
// and the migration selector all ask the same question of the same file, and four
// spellings of "where does the version live" is how a member ends up priced by one
// and converged by another.
//
// WHERE THEY LIVE (#1252). The engine version is the top-level `engineVersion`. A
// pack's version is `version` ON THAT PACK'S OWN ENTRY — the one place it cannot
// outlive what it prices: the central `claudinite.packVersions` map it replaces was
// keyed by a pack id nothing else in the file had to agree with, so a rename left a
// version priced against a pack the declaration no longer named.
//
// THE LEGACY BLOCK IS READ, NEVER WRITTEN. A member reaches the record that reshapes
// its file one converge AFTER the engine that can read the new shape, so every read
// here falls back to `claudinite` and every write leaves it exactly as it found it —
// the reshape is the record's single job, not something four writers do a bit of.
import { canonicalPackVersions } from './pack_loader/renamed-packs.mjs';
// `isVersion`, not `isDeclaredVersion`: the install floor (0) is a real state for a
// version a repo HAS — "below everything" — even though nothing may DECLARE it as a
// manifest's or a release's own number.
import { isVersion } from './version.mjs';

// The retired block. Named so the readers below and the #1252 record agree on the
// one spelling, and so Phase 3 has a symbol to grep for when it deletes the
// tolerance.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
export const LEGACY_STAMP_KEY = 'claudinite';

// `{ engineVersion, packVersions }` for a parsed settings object — the shape every
// caller already passes around as `installed`. Null versions rather than absent
// keys: "not installed" is a state of its own, and a caller comparing against a
// zero or an empty string would read a fresh mount as ancient.
export function installedVersions(raw) {
  const legacy = raw?.[LEGACY_STAMP_KEY] ?? null;
  const engineVersion = isVersion(raw?.engineVersion) ? raw.engineVersion
    : (isVersion(legacy?.engineVersion) ? legacy.engineVersion : null);

  const packVersions = {};
  const legacyPacks = legacy?.packVersions;
  if (legacyPacks && typeof legacyPacks === 'object' && !Array.isArray(legacyPacks)) {
    Object.assign(packVersions, canonicalPackVersions(legacyPacks));
  }
  for (const entry of Array.isArray(raw?.packs) ? raw.packs : []) {
    if (entry && typeof entry === 'object' && typeof entry.id === 'string' && isVersion(entry.version)) {
      packVersions[entry.id] = entry.version;
    }
  }
  return { engineVersion, packVersions };
}

// Has this repo been vendored at all? A mount that has never run stamps neither
// number, and every caller that used to ask "is there a stamp" is asking this.
export const hasInstalledMount = (raw) => {
  const { engineVersion, packVersions } = installedVersions(raw);
  return engineVersion !== null || Object.keys(packVersions).length > 0;
};

// The settings object with these versions recorded: `engineVersion` at the top,
// each pack's version on its own entry. Returned rather than written, so the caller
// that owns the file owns the write — and so this stays testable without one.
//
// A version for a pack the declaration does not carry is DROPPED, not appended as
// a bare entry: an entry is a declaration that the pack is active, and inventing
// one here would activate a pack nobody declared. A pack entry declared as a plain
// string is widened to an object so it can hold its version; every other property
// and the entry ORDER survive untouched, because this file is one a person reads.
export function withInstalledVersions(raw, { engineVersion, packVersions } = {}) {
  const next = { ...(raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}) };
  if (engineVersion !== undefined && engineVersion !== null) next.engineVersion = engineVersion;

  if (packVersions) {
    next.packs = (Array.isArray(next.packs) ? next.packs : []).map((entry) => {
      const id = typeof entry === 'string' ? entry : entry?.id;
      if (typeof id !== 'string' || !Object.hasOwn(packVersions, id)) return entry;
      const base = typeof entry === 'string' ? { id: entry } : { ...entry };
      // `version` sits directly after `id`, where a reader scanning the list for a
      // pack's version finds it beside the name rather than past its config. The
      // entry's OWN `version` is destructured out before the spread, not merely
      // overwritten by key order: leaving it in `rest` puts the stale number back
====
// WHAT A MEMBER'S SETTINGS FILE IS CALLED — the names alone, and nothing that
// touches a disk to find one.
//
// The names are split out from `settings-file.mjs` because one reader has no disk:
// the dashboard page runs this module in a browser, unbundled, and a single
// `node:` import anywhere in its graph fails the page's first module load
// (#1286). So the two halves live apart — the vocabulary here, the `existsSync`
// probe that picks between the names beside it — and `settings-file.mjs` re-exports
// everything below, which keeps it the one import every disk-side reader needs.
//
// THE RENAME (#1252). The file is `.claudinite-settings.json`. It was
// `.claudinite-checks.json` when checks were the only thing a member declared, and
// it has not been a file of checks for a long time: it carries the pack
// declaration, the scheduler anchor, the installed versions and the delivery
// override. The old name is still READ, everywhere, because a member's file is
// renamed by a migration record that converges on its own schedule — and until
// every member has run it, both names name the same file.
//
// The tolerance is the LEGACY half of a rename with a stated end: the cleanup that
// deletes it is due one convergence window after the advisory that reports the old
// name (#1640). Not "when no member still carries it" — the canon has no way to
// see that, so a gate phrased that way never opens.

export const SETTINGS_FILE = '.claudinite-settings.json';

// Retired from what anything WRITES; still read while members carry it.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
export const LEGACY_SETTINGS_FILE = '.claudinite-checks.json';

// Both names, newest first — the read order, so a member mid-rename that somehow
// holds both is read from the one the migration wrote. Exported for the cross-repo
// readers, which have no disk to probe and must try the paths in this order over
// the API.
export const SETTINGS_FILES = [SETTINGS_FILE, LEGACY_SETTINGS_FILE];

// Is this path one of the two settings-file names? For the scans that ask whether a
// changed file is the declaration, which must keep answering yes for a member that
// has not been renamed yet.
export const isSettingsFile = (path) => SETTINGS_FILES.includes(String(path ?? '').split('/').pop());
====
15:export default {
16:  // A migration record's declared `version` must be ≤ this number, and this number must
18:  // `migrationApplies` is `want > have` against the stamped version, and what gets
19:  // stamped is this manifest's number — so a record declaring a version above it would
21:  version: '60915.8',
34:  // FIXED barriers other active packs carry as manifest data
====
import { copyFileSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { computeVendorSet, SHARED_SUBDIR } from '../../../vendoring/compute-vendor-set.mjs';
import { loadPacks, resolveDeclaredPacks, packEntryId } from '../../../engine/pack_loader/pack-registry.mjs';
import { ENGINE_VERSION } from '../../../engine/version.mjs';
import { isVersion, versionAbove } from '../../../engine/version.mjs';
import { DECLARATION_FILE, migrationDirs, flowOf, recordVersion } from '../../../engine/checks/helpers/active-migrations.mjs';
import { settingsPath } from '../../../engine/settings-file.mjs';
import { installedVersions, hasInstalledMount, withInstalledVersions } from '../../../engine/installed-versions.mjs';
import { NEEDS_HUMAN, runSelfTest, deliveryDecision } from './engine-update.mjs';
import { isPackFile } from './pack-update.mjs';

// INSTALL = THE UPDATE FLOW FROM VERSION ZERO (docs/versioned-updates/DESIGN.md §4),
// with one difference that is not an optimisation but a correctness rule:
//
//   **AN INSTALL RUNS NO MIGRATIONS** (owner decision 9). The vendored content is
//   already the newest shape, so there is no older state to migrate. Replaying
//   history onto a fresh install is not merely wasted work — a record assumes the
//   shapes ITS ERA produced, and an empty repo is not one of them, so the replay is
//   a hazard. The install fetches no records and stamps the LATEST version directly;
//   migrations exist for repos installed at an older one.
//
// Everything else is the pack flow's: same vendor set, same self-test gate, same
// terminals. What differs is only where it starts.
//
// AN INSTALL IS NOT AN UPDATE IN DISGUISE. A pack the repo already has a version for
// is refused rather than reinstalled: reinstalling would stamp the newest version
// while skipping every record between, which is exactly how a member ends up
// claiming a state it was never migrated into.
const canonRoot = dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))); // <canon>/packs/claudinite-lifecycle/updates/<this file>

const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });

// Which of the requested ids this repo can actually install, and why the rest are
// refused. Pure over the pack set and the stamp, so the judgment is testable with
// no repo on disk.
export function planInstall(packs, ids, installed, { engineVersion = ENGINE_VERSION } = {}) {
  const byId = new Map(packs.map((p) => [p.id, p]));
  const stamped = installed?.packVersions ?? {};
  const install = [];
  const refused = [];
  for (const id of ids ?? []) {
    const pack = byId.get(id);
    if (!pack) { refused.push({ id, why: `"${id}" names no canon pack` }); continue; }
    if (isVersion(stamped[id])) {
      refused.push({ id, why: `"${id}" is already installed at version ${stamped[id]} — that is an update, not an install` });
      continue;
    }
    const needs = pack.minEngineVersion;
    if (isVersion(needs) && versionAbove(needs, engineVersion)) {
      refused.push({ id, why: `"${id}" needs engine ${needs}; this repo runs engine ${engineVersion}` });
      continue;
    }
    install.push({ id, version: pack.version ?? null });
  }
  return { install, refused };
}

// The questions this install cannot answer for the repo. An interview is not a
// special terminal (DESIGN §3.9) — unanswered questions end the run exactly like a
// red check does: PR open, `needs-human`, stop. It degrades gracefully to async,
// which is what the live-session adoption skill could never do.
export function unansweredQuestions(packs, entries) {
  const byId = new Map(packs.map((p) => [p.id, p]));
  const out = [];
  for (const entry of entries ?? []) {
    const id = packEntryId(entry);
    const pack = id === undefined ? undefined : byId.get(id);
    if (!pack?.questions?.length) continue;
    const answers = (typeof entry === 'object' && entry?.answers) || {};
    for (const q of pack.questions) {
      if (!q?.id || answers[q.id] !== undefined) continue;
      out.push({ pack: id, question: q.id, prompt: q.prompt ?? '' });
    }
  }
  return out;
}

// Install `ids` into `targetRoot`: declare them, vendor their content, stamp their
// latest versions, gate, and report. `dryRun` judges everything and writes nothing.
export async function installPacks(targetRoot, ids, {
  today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun, packs: packSet,
} = {}) {
  const settingsFile = settingsPath(targetRoot);
  if (!existsSync(settingsFile)) {
    return outcome(NEEDS_HUMAN, `${targetRoot} has no ${DECLARATION_FILE} — adoption seeds the declaration first`);
  }
  let raw;
  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); }
